# MythTV Python API Client Library

Here's a complete Python library to interact with the MythTV Services API:

## `mythtv_client/__init__.py`

```python
"""MythTV API Client Library"""
from .client import MythTVClient
from .exceptions import MythTVError, MythTVConnectionError, MythTVAPIError

__version__ = "0.1.0"
__all__ = ["MythTVClient", "MythTVError", "MythTVConnectionError", "MythTVAPIError"]
```

## `mythtv_client/exceptions.py`

```python
"""Custom exceptions for MythTV client"""


class MythTVError(Exception):
    """Base exception for MythTV client errors"""
    pass


class MythTVConnectionError(MythTVError):
    """Raised when connection to MythTV server fails"""
    pass


class MythTVAPIError(MythTVError):
    """Raised when the MythTV API returns an error"""
    def __init__(self, message, status_code=None, response=None):
        super().__init__(message)
        self.status_code = status_code
        self.response = response
```

## `mythtv_client/base.py`

```python
"""Base service class"""
import requests
from .exceptions import MythTVConnectionError, MythTVAPIError


class BaseService:
    """Base class for all MythTV services"""

    service_name = ""

    def __init__(self, client):
        self.client = client

    def _get(self, endpoint, params=None):
        return self.client._request("GET", f"{self.service_name}/{endpoint}", params=params)

    def _post(self, endpoint, data=None, params=None):
        return self.client._request("POST", f"{self.service_name}/{endpoint}", data=data, params=params)
```

