"""Myth service - general server functions"""
from ..base import BaseService


class MythService(BaseService):
    service_name = "Myth"

    def get_hosts(self):
        """Get list of all hosts known to the backend"""
        return self._get("GetHosts")

    def get_host_name(self):
        """Get hostname of the backend"""
        return self._get("GetHostName")

    def get_time_zone(self):
        """Get backend time zone information"""
        return self._get("GetTimeZone")

    def get_setting(self, key, hostname=None, default=None):
        """Get a setting value"""
        params = {"Key": key}
        if hostname:
            params["HostName"] = hostname
        if default is not None:
            params["Default"] = default
        return self._get("GetSetting", params=params)

    def put_setting(self, key, value, hostname=None):
        """Set a setting value"""
        data = {"Key": key, "Value": value}
        if hostname:
            data["HostName"] = hostname
        return self._post("PutSetting", data=data)

    def get_storage_groups(self, hostname=None, group_name=None):
        """List storage groups"""
        params = {}
        if hostname:
            params["HostName"] = hostname
        if group_name:
            params["GroupName"] = group_name
        return self._get("GetStorageGroupDirs", params=params)

    def get_logs(self, host_name=None, application=None, level="ERR", count=100):
        """Retrieve log entries"""
        params = {"Level": level, "MaxCount": count}
        if host_name:
            params["HostName"] = host_name
        if application:
            params["Application"] = application
        return self._get("GetLogs", params=params)

    def backup_database(self):
        """Trigger a database backup"""
        return self._post("BackupDatabase")

    def check_database(self, repair=False):
        """Run a database integrity check"""
        return self._post("CheckDatabase", data={"Repair": repair})
```

