"""DVR service - recordings and scheduling"""
from ..base import BaseService


class DvrService(BaseService):
    service_name = "Dvr"

    def get_recorded_list(self, descending=True, start_index=0, count=0,
                         title_regex=None, recording_group=None):
        """Get list of recorded programs"""
        params = {
            "Descending": descending,
            "StartIndex": start_index,
            "Count": count
        }
        if title_regex:
            params["TitleRegEx"] = title_regex
        if recording_group:
            params["RecGroup"] = recording_group
        return self._get("GetRecordedList", params=params)

    def get_recorded(self, recorded_id=None, chan_id=None, start_time=None):
        """Get a specific recording"""
        params = {}
        if recorded_id:
            params["RecordedId"] = recorded_id
        else:
            params["ChanId"] = chan_id
            params["StartTime"] = start_time
        return self._get("GetRecorded", params=params)

    def remove_recorded(self, recorded_id=None, chan_id=None, start_time=None,
                       force_delete=False, allow_rerecord=False):
        """Delete a recording"""
        data = {
            "ForceDelete": force_delete,
            "AllowRerecord": allow_rerecord
        }
        if recorded_id:
            data["RecordedId"] = recorded_id
        else:
            data["ChanId"] = chan_id
            data["StartTime"] = start_time
        return self._post("RemoveRecorded", data=data)

    def get_upcoming_list(self, start_index=0, count=0, show_all=False):
        """Get list of upcoming recordings"""
        params = {
            "StartIndex": start_index,
            "Count": count,
            "ShowAll": show_all
        }
        return self._get("GetUpcomingList", params=params)

    def get_conflict_list(self, start_index=0, count=0):
        """Get list of scheduling conflicts"""
        params = {"StartIndex": start_index, "Count": count}
        return self._get("GetConflictList", params=params)

    def get_expiring_list(self, start_index=0, count=0):
        """Get list of expiring recordings"""
        params = {"StartIndex": start_index, "Count": count}
        return self._get("GetExpiringList", params=params)

    def get_encoder_list(self):
        """Get list of encoders/tuners"""
        return self._get("GetEncoderList")

    def get_recording_rule_list(self, start_index=0, count=0):
        """Get all recording rules"""
        params = {"StartIndex": start_index, "Count": count}
        return self._get("GetRecordScheduleList", params=params)

    def add_recording_rule(self, rule_data):
        """Add a new recording rule"""
        return self._post("AddRecordSchedule", data=rule_data)

    def update_recording_rule(self, rule_data):
        """Update an existing recording rule"""
        return self._post("UpdateRecordSchedule", data=rule_data)

    def remove_recording_rule(self, rec_rule_id):
        """Remove a recording rule"""
        return self._post("RemoveRecordSchedule", data={"RecordId": rec_rule_id})

    def get_titles(self, rec_group=None):
        """Get unique titles of recordings"""
        params = {}
        if rec_group:
            params["RecGroup"] = rec_group
        return self._get("GetTitleList", params=params)

    def reschedule_recordings(self):
        """Trigger a reschedule"""
        return self._post("RescheduleRecordings")
```

