class CaptureService(BaseService):
    service_name = "Capture"

    def get_capture_card_list(self, host_name=None, card_type=None):
        """Get list of capture cards"""
        params = {}
        if host_name:
            params["HostName"] = host_name
        if card_type:
            params["CardType"] = card_type
        return self._get("GetCaptureCardList", params=params)

    def get_capture_card(self, card_id):
        """Get a specific capture card"""
        return self._get("GetCaptureCard", params={"CardId": card_id})

    def remove_capture_card(self, card_id):
        """Remove a capture card"""
        return self._post("RemoveCaptureCard", data={"CardId": card_id})
